    # ★ 결과는 소켓으로 POS에 push (pending은 이미 pop됐어도 지역변수에 참조가 남음)
    socketio.emit("toss_payment_result", {
        "payment_id": payment_id, "result": result, "payment_type": payment_type,
    }, to="pos_group")

