const COLS = 20, ROWS = 12, GAP = 16;
let CELL_W = 60, CELL_H = 60;

// 컨테이너 크기에서 셀 크기를 동적 계산 — GAP을 셀에 흡수시킨다
const updateCellSize = () => {
  const c = document.getElementById("table-canvas");
  CELL_W = (c.clientWidth  + GAP) / COLS;
  CELL_H = (c.clientHeight + GAP) / ROWS;
};

// 그리드 ↔ 픽셀
const gridToLeft   = gx => gx * CELL_W;
const gridToWidth  = gw => gw * CELL_W - GAP;   // -GAP = 카드 사이 간격
const leftToGrid   = px => Math.round(px / CELL_W);

card.addEventListener("pointerdown", (e) => {
  if (e.target.closest(".resize-handle, .card-actions")) return;  // 중첩 영역은 위임
  card.setPointerCapture(e.pointerId);
  const start = { x: e.clientX, y: e.clientY, left: rectLeft(card), top: rectTop(card) };
  let dragStarted = false;

  const onMove = (e) => {
    const dx = e.clientX - start.x, dy = e.clientY - start.y;
    if (!dragStarted && Math.hypot(dx, dy) > 5) {   // ★ 탭/드래그 분기
      dragStarted = true; card.classList.add("dragging");
    }
    if (!dragStarted) return;

    const gw = +card.dataset.gw, gh = +card.dataset.gh;
    // 이동 중엔 픽셀을 '자유롭게' 따라오게 (부드러움) + 경계 클램프
    const left = clamp(start.left + dx, 0, (COLS - gw) * CELL_W);
    const top  = clamp(start.top  + dy, 0, (ROWS - gh) * CELL_H);
    card.style.left = left + "px"; card.style.top = top + "px";

    const sx = leftToGrid(left), sy = topToGrid(top);
    if (sx !== prevSnapX || sy !== prevSnapY) {      // 셀을 넘을 때마다
      haptic();                                       // navigator.vibrate(30) — 태블릿 촉감
      card.dataset.gx = sx; card.dataset.gy = sy; prevSnapX = sx; prevSnapY = sy;
    }
  };

  const onUp = () => {
    if (!dragStarted) return handleCardClick(card);   // 탭이었음 → 선택/스왑
    dropCard(card);                                    // 드래그 종료 → 스냅·검증·저장
  };
  card.addEventListener("pointermove", onMove);
  card.addEventListener("pointerup", onUp);
});

const checkOverlap = (excludeId, gx, gy, gw, gh) => {
  for (const c of document.querySelectorAll(".table-card")) {
    if (String(c.dataset.id) === String(excludeId)) continue;
    const [cx, cy, cw, ch] = [+c.dataset.gx, +c.dataset.gy, +c.dataset.gw, +c.dataset.gh];
    if (gx < cx + cw && gx + gw > cx && gy < cy + ch && gy + gh > cy) return true;  // AABB
  }
  return false;
};

const dropCard = (card) => {
  card.classList.remove("dragging");
  const gw = +card.dataset.gw, gh = +card.dataset.gh;
  let gx = clamp(leftToGrid(px(card, "left")), 0, COLS - gw);   // 경계 클램프
  let gy = clamp(topToGrid (px(card, "top")),  0, ROWS - gh);

  if (checkOverlap(card.dataset.id, gx, gy, gw, gh)) {          // 겹치면 되돌림
    gx = +card.dataset.gx; gy = +card.dataset.gy;
    card.classList.add("overlap");                              // CSS shake 400ms
    setTimeout(() => card.classList.remove("overlap"), 400);
  }
  card.dataset.gx = gx; card.dataset.gy = gy;
  applyCardRect(card);                                          // DOM을 격자에 스냅
  syncTableData(+card.dataset.id, { grid_x: gx, grid_y: gy });
  autoSave();                                                   // ★ 자동저장
};

