# app/services/fsrs/core.py (요지)
DECAY  = -0.5
FACTOR = 0.9 ** (1.0 / DECAY) - 1.0   # ≈ 0.2346

def _stability_after_recall(w, d, s, r, rating):
    """정답 시 stability 갱신. 표준식: S·(1 + SInc)."""
    hard_penalty = w[15] if rating == HARD else 1.0
    easy_bonus   = w[16] if rating == EASY else 1.0
    sinc = (
        math.exp(w[8]) * (11.0 - d) * (s ** (-w[9]))
        * (math.exp((1.0 - r) * w[10]) - 1.0)
        * hard_penalty * easy_bonus
    )
    return max(s * (1.0 + sinc), s + 0.01)      # 단조 증가 보장 (B2)

def _stability_after_lapse(w, d, s, r):
    """오답 시. (1-R) 지수항으로 '밀려서 틀린 카드'는 덜 깎이게 (B3)."""
    new_s = (
        w[11] * (d ** (-w[12])) * ((s + 1.0) ** w[13] - 1.0)
        * math.exp(w[14] * (1.0 - r))
    )
    return max(new_s, 0.1)

def _next_interval(s, desired_retention=0.9):
    interval = s / FACTOR * (desired_retention ** (1.0 / DECAY) - 1.0)
    return max(1, min(round(interval), 36500))

# app/services/fsrs/scheduler.py (요지)
def _apply_soft_lapse(fsrs_result, stability_before, is_consecutive, prior_correct_rate):
    rate = 0.1 if is_consecutive else 0.3
    if prior_correct_rate is not None and prior_correct_rate >= 0.8:
        rate *= 0.5    # 의도는 "덜 깎기"였지만 rate 는 남기는 하한이라 실제로는 더 깎인다 (수정 대상)
    soft = max(stability_before * rate, 0.1)
    final = max(soft, float(fsrs_result['stability']))  # 급락 방지
    return {**fsrs_result, 'stability': round(final, 4)}

