def normalize_text(text: str) -> str:
    t = strip_html(text or "")                 # 예문의 <b> 강조 태그 방어
    t = unicodedata.normalize("NFC", t)         # 유니코드 정규화
    return re.sub(r"\s+", " ", t).strip()

def build_object_key(prefix, provider, model, voice, language, norm_text):
    h = hashlib.sha256(norm_text.encode("utf-8")).hexdigest()
    return f"{prefix}/{provider}/{model}/{voice}/{language}/{h[:2]}/{h}.mp3"

