FALLBACK_PROVIDER = "gtts"

def ensure_cached(text, language, provider=None, storage=None, allow_fallback=True):
    provider = provider or get_provider_for_language(language)
    norm = normalize_text(text)
    key = object_key_for(provider, language, norm)

    if storage.exists(key):
        return key, False                       # 캐시 히트 — 외부 API 호출 0

    try:
        result = provider.synthesize(norm, language)
    except TTSGenerationError:
        if not allow_fallback:
            raise
        fb = get_provider(FALLBACK_PROVIDER)
        key = object_key_for(fb, language, norm)   # provider 다르면 키도 달라짐
        result = fb.synthesize(norm, language)

    storage.put_audio(key, result.audio, result.content_type, metadata={
        "text": quote(norm), "lang": language, "provider": provider.name,   # ASCII 위해 URL-encode
    })
    return key, True

