def exists(self, key: str) -> bool:
    try:
        return any(o.object_name == key
                   for o in self._client.list_objects(self.bucket, prefix=key, recursive=True))
    except S3Error:
        return False        # 조회 실패 시 보수적으로 '없음'(put이 멱등하게 덮음)

