async function authenticateDaemon(req) {
  const raw = bearerFrom(req.headers.authorization);
  if (!raw) throw new UnauthorizedError();

  const device = await DaemonDevice.findOne({
    where: { token_hash: sha256(raw), revoked_at: null },
  });
  if (!device) throw new UnauthorizedError();
  return device;               // → 이후 모든 프레임은 이 계정 경계 안에서만 라우팅된다
}

