// 모든 프리셋이 반드시 이 함수를 통과해서 나간다.
// 프리셋이 이걸 틀리거나 잊을 수 있는 방법이 없어야 한다.
fn composite(raw: vec3<f32>, p: vec2<f32>) -> vec4<f32> {
    let L = raw * u.state.w * cursor_cut(p);   // 세기 · 커서 컷스루
    let a = max(max(L.r, L.g), L.b);
    if (a <= 0.0) {
        return vec4<f32>(0.0);                 // 완전 투명 — 그리지 않음
    }
    let straight_srgb = linear_to_srgb(L / a); // ① 스트레이트로 인코딩
    return vec4<f32>(straight_srgb * a, a);    // ② 그 다음에 프리멀티플라이
}

