// 고친 구현: 24 → 56pt 에 걸쳐 램프
fn readability_gate(intensity: f32, d_edge: f32) -> f32 {
    let gate = mix(1.0, 0.40, smoothstep(24.0, 56.0, d_edge));
    return min(intensity, gate);
}

