// 우리가 낸 1 kHz 사인만 골라내는 Goertzel — 배경 음악이 통과해도 거짓 양성이 안 난다.
func goertzelEnergy(_ samples: [Float], targetHz: Float, sampleRate: Float) -> Float {
    let k = (Float(samples.count) * targetHz / sampleRate).rounded()
    let w = 2 * Float.pi * k / Float(samples.count)
    let coeff = 2 * cos(w)
    var s0: Float = 0, s1: Float = 0, s2: Float = 0
    for x in samples {
        s0 = x + coeff * s1 - s2
        s2 = s1; s1 = s0
    }
    return sqrt(s1 * s1 + s2 * s2 - coeff * s1 * s2) / Float(samples.count) * 2
}

/// 실시간 오디오 스레드에서 호출된다. 할당·락·시스템 호출 금지.
/// 여기서는 정말로 '쓰기'만 한다 — 판단은 전부 분석 스레드에서.
#[no_mangle]
pub extern "C" fn lambent_audio_push(
    engine: *mut Engine,
    frames: *const f32,   // 인터리브드 스테레오
    frame_count: usize,
) {
    let Some(engine) = (unsafe { engine.as_mut() }) else { return };
    let src = unsafe { std::slice::from_raw_parts(frames, frame_count * 2) };
    // 링버퍼가 가득 차면 조용히 버린다. 실시간 스레드는 절대 기다리지 않는다.
    let _ = engine.ring.push_slice(src);
}

