/// 키 유도의 도메인 분리.
/// 없으면 같은 서명 바이트가 '서명을 해시하는 다른 모든 문맥'에서 키 재료로 재사용될 수 있다.
/// 비용이 0이고 교차 프로토콜 혼동 한 부류를 통째로 닫는다.
const KDF_DOMAIN: &[u8] = b"lambent.v1.content-key-unwrap";

pub(crate) fn unwrap_key_from_signature(signature: &[u8; 64]) -> [u8; 32] {
    let mut h = Sha512::new();
    h.update(KDF_DOMAIN);
    h.update(signature);
    let d = h.finalize();
    let mut out = [0u8; 32];
    out.copy_from_slice(&d[..32]);
    out
}

