/// 이 맥의 하드웨어 UUID(IOPlatformUUID)의 SHA-256 (hex).
///
/// 해시로 만드는 이유: 원본 하드웨어 식별자가 이 기기를 떠나지도, 라이선스 안에 들어가지도
/// 않게 하기 위해서다. 서버와 라이선스는 오직 해시만 본다.
/// 재설치·네트워크 변경에 안정적이고(MAC 주소와 달리), 로직보드를 갈 때만 바뀐다.
static func current() -> String? {
    guard let uuid = hardwareUUID() else { return nil }
    return SHA256.hash(data: Data(uuid.utf8)).map { String(format: "%02x", $0) }.joined()
}

// 빌드 시점에 죽는다. 런타임에 조용히 절반만 쓰는 것보다 낫다.
fn parse_key_hex(s: &str) -> [u8; 32] {
    assert_eq!(s.len(), 64, "content key must be exactly 64 hex chars, got {}", s.len());
    let mut out = [0u8; 32];
    for (i, b) in out.iter_mut().enumerate() {
        *b = u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).expect("non-hex in content key");
    }
    out
}

