/// 왜 이게 독립된 이름 있는 함수인가:
/// `h + 38` 로 인라인하면 방향이 사라진다. 그러면 파란 아트가 보라 팔레트를 만들고,
/// 출력은 여전히 '유효한 팔레트'이므로 **어떤 테스트도 잡지 못한다.**
/// 열은 레벨에서 오지 위치나 색상 번호에서 오지 않는다.
fn toward_hot(h: f32, degrees: f32) -> f32 {
    const HOT: f32 = 90.0;                    // 흑체 축의 뜨거운 끝
    let delta = shortest_arc(h, HOT);         // -180..180
    (h + degrees * delta.signum()).rem_euclid(360.0)
}

