const startStreaming = async (roomSlug: string) => {
  const alwaysOn = useAlwaysOnCamera.getState();
  if (!alwaysOn.stream || !alwaysOn.isActive) await alwaysOn.start();
  const stream = useAlwaysOnCamera.getState().stream;
  if (!stream) return;

  const { token } = await emitWithAck('room:join', { roomSlug });
  await connectToRoom(token);

  const videoTrack = stream.getVideoTracks()[0];
  videoTrack.contentHint = 'motion';
  await publishTrack(videoTrack, 'camera');

  // 마이크는 발행하지 않는다 — 같은 물리 공간의 두 마이크는 하울링을 만든다.
