// 홈서버의 100 Mb/s NIC 가 무제한 HD 스트림을 감당할 수 없다.
// 한 사용자가 한 방에 들이는 카메라는 현재 기기 포함 최대 3대.
const MAX_DEVICES_PER_USER = 3;

let inRoom = cameras.filter((c) => c.isCurrentDevice || c.isInRoom).length;
for (const cam of cameras) {
  if (cam.isCurrentDevice) continue;
  if (!cam.isOnline) { autoStartedRef.current.delete(cam.id); continue; }   // 재접속하면 다시 후보
  if (cam.isInRoom
      || manualStopRef.current.has(cam.id)      // 사용자가 직접 끈 기기는 되살리지 않는다
      || autoStartedRef.current.has(cam.id)) continue;
  if (inRoom >= MAX_DEVICES_PER_USER) break;
  autoStartedRef.current.add(cam.id);
  inRoom++;
  emitWithAck('camera:requestStart', { targetDeviceId: cam.id, roomSlug: slug });
}

