socket.on('preview:request', async ({ targetDeviceId }, callback) => {
  if (targetDeviceId === deviceId) return callback?.({ error: 'cannot preview self' });

  const target = await Device.findOne({
    where: { id: targetDeviceId, user_id: user.userId, is_active: true },  // ★ 같은 소유자만
  });
  if (!target?.is_online || !target.socket_id) return callback?.({ error: 'offline' });

  const turnCredentials = generateTurnCredentials(user.userId);   // HMAC ephemeral
  io.to(target.socket_id).emit('preview:requested', {
    viewerSocketId: socket.id,
    viewerDeviceId: deviceId,
    iceServers: turnCredentials.iceServers,
  });
  callback?.({ success: true, iceServers: turnCredentials.iceServers });
});

socket.on('preview:requested', async ({ viewerSocketId, iceServers }) => {
  let cam = useAlwaysOnCamera.getState();
  let videoTrack = cam.getVideoTrack();
  if (!videoTrack) { await cam.start(); videoTrack = useAlwaysOnCamera.getState().getVideoTrack(); }
  if (!videoTrack) {
    socket.emit('preview:noTrack', { targetSocketId: viewerSocketId, reason: 'no_camera' });
    return;   // "카메라 꺼짐" 상태를 뷰어에 정확히 알려준다
  }

  const pc = new RTCPeerConnection({ iceServers: iceServers?.length ? iceServers : FALLBACK_ICE });
  for (const t of new MediaStream([videoTrack]).getTracks()) pc.addTrack(t);
  pc.onicecandidate = (e) => e.candidate &&
    socket.emit('preview:ice', { targetSocketId: viewerSocketId, candidate: e.candidate });

  const offer = await pc.createOffer();
  await pc.setLocalDescription(offer);
  socket.emit('preview:offer', { targetSocketId: viewerSocketId, sdp: offer.sdp });
});

export function generateTurnCredentials(userId: string) {
  const ttl = 86400;                                          // 24시간
  const timestamp = Math.floor(Date.now() / 1000) + ttl;
  const username = `${timestamp}:${userId}`;                  // 만료시각이 사용자명에 박힌다
  const credential = crypto.createHmac('sha1', TURN_SECRET)
                           .update(username).digest('base64');
  return {
    iceServers: [{ urls: STUN_SERVER }, { urls: [TURN_SERVER, TURNS_SERVER], username, credential }],
    iceTransportPolicy: 'all' as const,
  };
}

